# TF-IDF Hyperparameters (Sparse Lexical & Behavioral)
# Based on solution lesson: Unigrams/Bigrams, Top 3000, sublinear_tf
TFIDF_PARAMS = {
    "max_features": 3000,
    "ngram_range": (1, 2),
    "min_df": 5,
    "sublinear_tf": True,
    "stop_words": "english",
    "lowercase": True,
}

# Dense Embedding Model
MPNET_MODEL_NAME = "all-mpnet-base-v2"

# =============================================================================
# MODEL HYPERPARAMETERS
# =============================================================================

# 1. Random Forest (Lexical Bagger & Community Bagger)
# Regularized with min_samples_leaf=2 to prevent overfitting on sparse data
RF_PARAMS = {
    "n_estimators": 300,
    "min_samples_leaf": 2,
    "class_weight": "balanced",
    "random_state": RANDOM_SEED,
    "n_jobs": -1,
    "verbose": 0,
}

# 2. XGBoost (Semantic Booster)
# Tuned for dense embeddings with early stopping capability
# scale_pos_weight ~3.0 handles the 75/25 class imbalance
XGB_PARAMS = {
    "n_estimators": 1000,
    "learning_rate": 0.05,
    "max_depth": 4,
    "subsample": 0.8,
    "colsample_bytree": 0.8,
    "scale_pos_weight": 3.0,
    "random_state": RANDOM_SEED,
    "n_jobs": -1,
    "verbosity": 0,
    "early_stopping_rounds": 50,
    "objective": "binary:logistic",
    "eval_metric": "auc",
}

# 3. k-Nearest Neighbors (Manifold Neighbor)
# Uses Cosine similarity to exploit embedding space structure
KNN_PARAMS = {
    "n_neighbors": 20,
    "metric": "cosine",
    "weights": "distance",
    "n_jobs": -1,
}

# 4. Logistic Regression (Contextual Anchor & Meta-Learner)
# High-bias regularizer
LR_PARAMS = {
    "C": 0.1,
    "penalty": "l2",
    "solver": "liblinear",
    "class_weight": "balanced",
    "random_state": RANDOM_SEED,
}
